import math

import pytest

from outbreak.analysis import analyse, analyse_exposure, rank_by_risk_ratio
from outbreak.line_list import EXPOSURES, two_by_two
from outbreak.report import render_report

EXPECTED_MARGINALS = {
    # exposure: (eaters, ill among eaters, non-eaters, ill among non-eaters)
    "salad": (30, 24, 10, 2),
    "chicken": (20, 13, 20, 13),
    "cake": (15, 9, 25, 17),
}


@pytest.fixture(scope="module")
def records():
    from outbreak import load_line_list

    return load_line_list()


@pytest.fixture(scope="module")
def results(records):
    return {r.exposure: r for r in analyse(records)}


# ---------------------------------------------------------------- fixture integrity


def test_line_list_sums_to_40_rows(records):
    assert len(records) == 40


def test_all_flags_binary(records):
    for r in records:
        for field in ("ate_salad", "ate_chicken", "ate_cake", "ill"):
            assert getattr(r, field) in (0, 1)


@pytest.mark.parametrize("exposure", EXPOSURES)
def test_constructed_marginals_match_spec(records, exposure):
    cells = two_by_two(records, exposure)
    eaters, ill_eaters, noneaters, ill_noneaters = EXPECTED_MARGINALS[exposure]
    assert cells["a"] == ill_eaters          # exposed & ill
    assert cells["a"] + cells["b"] == eaters  # all exposed
    assert cells["c"] == ill_noneaters        # unexposed & ill
    assert cells["c"] + cells["d"] == noneaters
    assert cells["a"] + cells["b"] + cells["c"] + cells["d"] == 40


def test_total_ill_is_consistent_across_exposures(records):
    ills = {exp: two_by_two(records, exp)["a"] + two_by_two(records, exp)["c"]
            for exp in EXPOSURES}
    assert set(ills.values()) == {26}


# ------------------------------------------------------- pinned point estimates


def test_salad_attack_rates_and_rr_exact(results):
    salad = results["salad"]
    assert salad.ar_exposed == pytest.approx(0.80)      # 24/30
    assert salad.ar_unexposed == pytest.approx(0.20)    # 2/10
    assert salad.risk_ratio == pytest.approx(4.0)       # exactly 4.0


def test_chicken_rr_is_exactly_one(results):
    assert results["chicken"].risk_ratio == pytest.approx(1.0)
    assert results["chicken"].ar_exposed == pytest.approx(13 / 20)
    assert results["chicken"].ar_unexposed == pytest.approx(13 / 20)


def test_cake_rr_below_one(results):
    cake = results["cake"]
    assert cake.risk_ratio == pytest.approx((9 / 15) / (17 / 25))
    assert cake.risk_ratio < 1


# ------------------------------------------------------------ Katz log CIs


def test_katz_ci_formula_matches_manual_computation(results):
    a, b, c, d = 24, 6, 2, 8  # salad 2x2
    se = math.sqrt(1 / a - 1 / (a + b) + 1 / c - 1 / (c + d))
    lo, hi = math.exp(math.log(4.0) - 1.96 * se), math.exp(math.log(4.0) + 1.96 * se)
    assert results["salad"].ci_low == pytest.approx(lo)
    assert results["salad"].ci_high == pytest.approx(hi)


def test_salad_ci_excludes_one_but_chickens_includes_it(results):
    assert results["salad"].ci_low > 1 and results["salad"].ci_high > 1
    assert results["chicken"].ci_low < 1 < results["chicken"].ci_high


# ------------------------------------------------------- ranking & zero cells


def test_ranked_table_orders_by_rr_descending(results):
    ranked = rank_by_risk_ratio(list(results.values()))
    rrs = [r.risk_ratio for r in ranked]
    assert rrs == sorted(rrs, reverse=True)
    assert [r.exposure for r in ranked] == ["salad", "chicken", "cake"]


def test_zero_cell_returns_none_with_continuity_note():
    res = analyse_exposure({"a": 0, "b": 10, "c": 5, "d": 5})
    assert res.risk_ratio is None
    assert res.ci_low is None and res.ci_high is None
    assert res.note is not None and "continuity" in res.note.lower()
    assert res.ar_exposed == 0.0 and res.ar_unexposed == pytest.approx(0.5)


def test_other_zero_cell_also_handled():
    res = analyse_exposure({"a": 8, "b": 2, "c": 0, "d": 10})
    assert res.risk_ratio is None
    assert "continuity" in res.note.lower()


# ------------------------------------------------------------------ report


def test_report_renders_without_error(records, results):
    text = render_report(
        list(results.values()), len(records),
        sum(two_by_two(records, e)["a"] + two_by_two(records, e)["c"] for e in EXPOSURES[:1]),
    )
    assert "salad" in text and "chicken" in text and "cake" in text

